import math
from functools import reduce

def lcm(a: int, b: int) -> int:
    return abs(a * b) // math.gcd(a, b)

def gcd(arr: List[int]) -> int:
    return reduce(math.gcd, arr)

def lcm_multiple(arr: List[int]) -> int:
    return reduce(lcm, arr)

def maxLength(nums: List[int]) -> int:
    n = len(nums)
    max_length = 0
    for i in range(n):
        product = 1
        current_gcd = nums[i]
        current_lcm = nums[i]
        for j in range(i, n):
            product *= nums[j]
            current_gcd = math.gcd(current_gcd, nums[j])
            current_lcm = lcm(current_lcm, nums[j])
            if product == current_gcd * current_lcm:
                max_length = max(max_length, j - i + 1)
    return max_length

from typing import List

def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    for i in range(len(grid)):
        if i % 2 == 0:
            # Traverse left to right
            for j in range(len(grid[i])):
                if j % 2 == 0:
                    result.append(grid[i][j])
        else:
            # Traverse right to left
            for j in range(len(grid[i]) - 1, -1, -1):
                if (j + 1) % 2 == 0:
                    result.append(grid[i][j])
    return result

from collections import Counter

def maxDifference(s: str) -> int:
    freq = Counter(s)
    max_odd = float('-inf')
    min_even = float('inf')
    max_even = float('-inf')
    min_odd = float('inf')

    for count in freq.values():
        if count % 2 == 0:
            min_even = min(min_even, count)
            max_even = max(max_even, count)
        else:
            max_odd = max(max_odd, count)
            min_odd = min(min_odd, count)

    return max(max_odd - min_even, max_even - min_odd)

def hasSpecialSubstring(s: str, k: int) -> bool:
    n = len(s)
    for i in range(n - k + 1):
        substring = s[i:i + k]
        if len(set(substring)) == 1:
            before = s[i - 1] if i > 0 else None
            after = s[i + k] if i + k < n else None
            if (before is None or before != substring[0]) and (after is None or after != substring[0]):
                return True
    return False

